import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { generatePersona } from '../api/client'
import { saveProfile } from '../lib/localStorage'
import type { ProfileAnswers } from '../types'

const SITUATIONS = ['refugee', 'worker', 'student', 'retired', 'small_business'] as const
const CONCERNS = ['money', 'housing', 'work', 'family', 'health'] as const

export default function ProfileWizard() {
  const navigate = useNavigate()
  const [step, setStep] = useState(0)
  const [answers, setAnswers] = useState<Partial<ProfileAnswers>>({})
  const [loading, setLoading] = useState(false)

  async function handleFinish(finalAnswers: ProfileAnswers) {
    setLoading(true)
    try {
      const persona = await generatePersona(finalAnswers)
      saveProfile({ answers: finalAnswers, persona })
      navigate('/chat')
    } finally {
      setLoading(false)
    }
  }

  function next(update: Partial<ProfileAnswers>) {
    const merged = { ...answers, ...update }
    setAnswers(merged)
    if (step < 4) {
      setStep(step + 1)
    } else {
      handleFinish(merged as ProfileAnswers)
    }
  }

  return (
    <div className="min-h-screen bg-neutral-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-2xl shadow-sm p-8">
        <div className="flex gap-1 mb-8">
          {[0, 1, 2, 3, 4].map((i) => (
            <div key={i} className={`h-1 flex-1 rounded-full ${i <= step ? 'bg-blue-500' : 'bg-neutral-200'}`} />
          ))}
        </div>
        {step === 0 && <Step1 onNext={(name) => next({ name })} initial={answers.name ?? ''} />}
        {step === 1 && <Step2 onNext={(situation) => next({ situation })} initial={answers.situation} />}
        {step === 2 && <Step3 onNext={(city) => next({ city })} initial={answers.city ?? ''} />}
        {step === 3 && <Step4 onNext={(concern) => next({ concern })} initial={answers.concern} />}
        {step === 4 && <Step5 onNext={(language) => next({ language })} initial={answers.language ?? ''} loading={loading} />}
      </div>
    </div>
  )
}

function Step1({ onNext, initial }: { onNext: (v: string) => void; initial: string }) {
  const [value, setValue] = useState(initial)
  return (
    <div>
      <h2 className="text-xl font-semibold mb-6">What's your name?</h2>
      <input
        className="w-full border border-neutral-200 rounded-lg px-4 py-3 mb-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="Your name"
      />
      <button className="w-full bg-blue-500 text-white py-3 rounded-lg font-medium disabled:opacity-40" disabled={!value.trim()} onClick={() => onNext(value.trim())}>
        Next
      </button>
    </div>
  )
}

function Step2({ onNext, initial }: { onNext: (v: ProfileAnswers['situation']) => void; initial?: ProfileAnswers['situation'] }) {
  const [value, setValue] = useState<ProfileAnswers['situation'] | undefined>(initial)
  return (
    <div>
      <h2 className="text-xl font-semibold mb-6">What's your situation?</h2>
      <div className="flex flex-col gap-2 mb-6">
        {SITUATIONS.map((s) => (
          <label key={s} className="flex items-center gap-3 cursor-pointer">
            <input type="radio" name="situation" value={s} checked={value === s} onChange={() => setValue(s)} />
            <span className="capitalize">{s.replace('_', ' ')}</span>
          </label>
        ))}
      </div>
      <button className="w-full bg-blue-500 text-white py-3 rounded-lg font-medium disabled:opacity-40" disabled={!value} onClick={() => value && onNext(value)}>
        Next
      </button>
    </div>
  )
}

function Step3({ onNext, initial }: { onNext: (v: string) => void; initial: string }) {
  const [value, setValue] = useState(initial)
  return (
    <div>
      <h2 className="text-xl font-semibold mb-6">Which city do you live in?</h2>
      <input
        className="w-full border border-neutral-200 rounded-lg px-4 py-3 mb-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="Your city"
      />
      <button className="w-full bg-blue-500 text-white py-3 rounded-lg font-medium disabled:opacity-40" disabled={!value.trim()} onClick={() => onNext(value.trim())}>
        Next
      </button>
    </div>
  )
}

function Step4({ onNext, initial }: { onNext: (v: ProfileAnswers['concern']) => void; initial?: ProfileAnswers['concern'] }) {
  const [value, setValue] = useState<ProfileAnswers['concern'] | undefined>(initial)
  return (
    <div>
      <h2 className="text-xl font-semibold mb-6">What's your biggest concern right now?</h2>
      <div className="flex flex-col gap-2 mb-6">
        {CONCERNS.map((c) => (
          <label key={c} className="flex items-center gap-3 cursor-pointer">
            <input type="radio" name="concern" value={c} checked={value === c} onChange={() => setValue(c)} />
            <span className="capitalize">{c}</span>
          </label>
        ))}
      </div>
      <button className="w-full bg-blue-500 text-white py-3 rounded-lg font-medium disabled:opacity-40" disabled={!value} onClick={() => value && onNext(value)}>
        Next
      </button>
    </div>
  )
}

function Step5({ onNext, initial, loading }: { onNext: (v: string) => void; initial: string; loading: boolean }) {
  const [value, setValue] = useState(initial)
  return (
    <div>
      <h2 className="text-xl font-semibold mb-6">What language do you prefer?</h2>
      <input
        className="w-full border border-neutral-200 rounded-lg px-4 py-3 mb-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="e.g. Ukrainian, Arabic, English"
      />
      <button
        className="w-full bg-blue-500 text-white py-3 rounded-lg font-medium disabled:opacity-40"
        disabled={!value.trim() || loading}
        onClick={() => onNext(value.trim())}
      >
        {loading ? 'Setting up your profile…' : 'Finish'}
      </button>
    </div>
  )
}
```

