import { useState } from 'react'
import { Navigate } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { getProfile } from '../lib/localStorage'
import { fetchNotes } from '../api/client'
import ProfileChip from '../components/ProfileChip'
import NotesSidebar from '../components/NotesSidebar'
import ChatMessages from '../components/ChatMessages'
import ChatInput from '../components/ChatInput'
import PDFUpload from '../components/PDFUpload'
import type { Message } from '../types'

export default function ChatPage() {
  const profile = getProfile()
  const [messages, setMessages] = useState<Message[]>([])

  const { data: noteGroups = [] } = useQuery({
    queryKey: ['notes', messages.length],
    queryFn: () => fetchNotes(messages, profile!.persona),
    refetchInterval: 15 * 60 * 1000,
    enabled: !!profile && messages.length >= 2,
  })

  if (!profile) return <Navigate to="/" replace />

  return (
    <div className="h-screen flex flex-col bg-neutral-50">
      <div className="flex items-center justify-end px-6 py-3 bg-white border-b border-neutral-100">
        <ProfileChip profile={profile} />
      </div>
      <div className="flex flex-1 overflow-hidden">
        <aside className="w-72 border-r border-neutral-100 bg-white flex flex-col overflow-y-auto">
          <NotesSidebar groups={noteGroups} />
          <div className="border-t border-neutral-100 p-4">
            <PDFUpload persona={profile.persona} />
          </div>
        </aside>
        <main className="flex-1 flex flex-col overflow-hidden">
          <ChatMessages messages={messages} />
          <ChatInput
            persona={profile.persona}
            messages={messages}
            onNewMessage={(msg, reply) =>
              setMessages((prev) => [
                ...prev,
                { role: 'user', content: msg },
                { role: 'assistant', content: reply },
              ])
            }
          />
        </main>
