import { useEffect, useRef } from 'react'
import type { Message } from '../types'

interface Props {
  messages: Message[]
}

export default function ChatMessages({ messages }: Props) {
  const bottomRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  if (messages.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-neutral-400 text-sm">
        Ask me anything about policies, benefits, or your rights.
      </div>
    )
  }

  return (
    <div className="flex-1 overflow-y-auto px-6 py-4 flex flex-col gap-3">
      {messages.map((m, i) => (
        <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div
            className={`max-w-[75%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${
              m.role === 'user'
                ? 'bg-blue-500 text-white rounded-br-sm'
                : 'bg-white border border-neutral-100 text-neutral-800 rounded-bl-sm shadow-sm'
            }`}
          >
            {m.content}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  )
}

import { useState } from 'react'
import { sendChatMessage } from '../api/client'
import type { Message } from '../types'

interface Props {
  persona: string
  messages: Message[]
  onNewMessage: (userMsg: string, assistantReply: string) => void
}

export default function ChatInput({ persona, messages, onNewMessage }: Props) {
  const [text, setText] = useState('')
  const [loading, setLoading] = useState(false)

  async function handleSend() {
    const msg = text.trim()
    if (!msg || loading) return
    setText('')
    setLoading(true)
    try {
      const reply = await sendChatMessage(msg, messages, persona)
      onNewMessage(msg, reply)
    } catch {
      onNewMessage(msg, 'Sorry, something went wrong. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="px-6 py-4 border-t border-neutral-100 bg-white">
      <div className="flex gap-3">
        <input
          className="flex-1 border border-neutral-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder={loading ? 'Thinking…' : 'Ask me anything…'}
          value={text}
          disabled={loading}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSend()}
        />
        <button
          onClick={handleSend}
          disabled={!text.trim() || loading}
          className="bg-blue-500 text-white px-5 py-3 rounded-xl text-sm font-medium disabled:opacity-40 hover:bg-blue-600 transition-colors"
        >
          Send
        </button>
      </div>
    </div>
  )
}

